void recovery_rollback(const std::string& path,const std::vector<std::string>& imports){
    {PersistenceService store(path,imports);root(store,"rollback-root");const auto captured=lease("rollback-root","rollback-generation");store.admit_agent_worker(captured).get();start(store,"rollback-root","rollback-attempt");store.claim_agent_worker_model(claim(captured,"rollback-attempt")).get();store.close();}
    std::vector<std::vector<SqlValue>> before_runs,before_attempts,before_workers,before_budget,before_events;
    const std::string workers="SELECT category,id,payload FROM information WHERE category IN ('native-agent-worker-leases','native-agent-worker-current','native-agent-worker-model-claims') ORDER BY category,id";
    {XlangSqlite sql(path,imports);before_runs=sql.execute("SELECT id,state FROM runs ORDER BY id").rows;before_attempts=sql.execute("SELECT root_run_id,attempt_id,state FROM agent_model_call_reservations ORDER BY root_run_id,attempt_id").rows;before_workers=sql.execute(workers).rows;before_budget=sql.execute("SELECT * FROM agent_execution_budgets ORDER BY root_run_id").rows;before_events=sql.execute("SELECT seq,run_id,kind,payload FROM events ORDER BY seq").rows;
        sql.execute("CREATE TRIGGER fixture_worker_recovery_abort BEFORE UPDATE ON information WHEN OLD.category='native-agent-worker-leases' AND json_extract(NEW.payload,'$.state')='retired' BEGIN SELECT RAISE(ABORT,'fixture_worker_recovery_abort'); END");}
    bool observed=false;try{PersistenceService blocked(path,imports);blocked.close();}catch(const DatabaseError& error){observed=std::string(error.what()).find("fixture_worker_recovery_abort")!=std::string::npos;}require(observed,"Recovery fixture must hit its actual injected worker-retirement fault");
    {XlangSqlite sql(path,imports);require(sql.execute("SELECT id,state FROM runs ORDER BY id").rows==before_runs&&sql.execute("SELECT root_run_id,attempt_id,state FROM agent_model_call_reservations ORDER BY root_run_id,attempt_id").rows==before_attempts&&sql.execute(workers).rows==before_workers&&sql.execute("SELECT * FROM agent_execution_budgets ORDER BY root_run_id").rows==before_budget&&sql.execute("SELECT seq,run_id,kind,payload FROM events ORDER BY seq").rows==before_events,"Failed worker retirement must roll back all run, attempt, worker, budget and event recovery writes");sql.execute("DROP TRIGGER fixture_worker_recovery_abort");}
    {PersistenceService store(path,imports);const auto recovered=store.agent_worker_lease("rollback-generation").get();require(store.run("rollback-root").get().state==RunState::failed&&recovered.state=="retired"&&recovered.retirement_reason=="backend_recovery"&&store.agent_worker_model_claim("rollback-root","rollback-attempt").get().state=="uncertain"&&store.root_budget("rollback-root").get().model_calls_reserved==1,"Corrected recovery must retain the original charged attempt without redispatch");store.close();}
}

