int main(int argc,char** argv){if(argc!=4)return 2;std::filesystem::path folder;try{std::random_device random;for(unsigned i=0;i<32;++i){auto candidate=std::filesystem::temp_directory_path()/("xmind-worker-ledger-"+std::to_string(random())+"-"+std::to_string(random()));if(std::filesystem::create_directory(candidate)){folder=std::move(candidate);break;}}require(!folder.empty(),"Cannot create isolated worker ledger fixture");const std::vector<std::string> imports{argv[1],argv[2]};ledger((folder/"ledger.sqlite").string(),imports);recovery_rollback((folder/"rollback.sqlite").string(),imports);model_host((folder/"model.sqlite").string(),imports,argv[3]);std::cout<<"Durable worker admission, duplicate dispatch, replacement, uncertainty, exact receipts and backend-owned model transport passed; no child AgentRunner RPC is implemented.\n";std::filesystem::remove_all(folder);return 0;}catch(const std::exception& error){std::cerr<<error.what()<<"; retained fixture "<<folder.string()<<'\n';return 1;}}
